/**
 * A deliberately tiny markdown subset for AeroWiki articles.
 *
 * The previous implementation built HTML strings and injected them with
 * `dangerouslySetInnerHTML`. Wiki content is meant to be generated by an LLM
 * agent, so that was a stored-XSS waiting to happen. This parser returns plain
 * tokens; React escapes them on render, so markup in the source is inert text.
 */

export type InlineTokenType = 'text' | 'strong' | 'em' | 'code';

export interface InlineToken {
  type: InlineTokenType;
  value: string;
}

export type Block =
  | { type: 'heading'; text: string }
  | { type: 'list'; items: InlineToken[][] }
  | { type: 'paragraph'; tokens: InlineToken[] };

const INLINE_PATTERN = /(\*\*[^*]+\*\*|`[^`]+`|\*[^*\n]+\*)/g;
const HEADING_PATTERN = /^\*\*([^*\n]+)\*\*$/;
const LIST_ITEM_PATTERN = /^\s*(?:[-*]|\d+\.)\s+/;

export function parseInline(text: string): InlineToken[] {
  const tokens: InlineToken[] = [];
  let cursor = 0;

  for (const match of text.matchAll(INLINE_PATTERN)) {
    const index = match.index ?? 0;
    if (index > cursor) {
      tokens.push({ type: 'text', value: text.slice(cursor, index) });
    }

    const raw = match[0];
    if (raw.startsWith('**')) {
      tokens.push({ type: 'strong', value: raw.slice(2, -2) });
    } else if (raw.startsWith('`')) {
      tokens.push({ type: 'code', value: raw.slice(1, -1) });
    } else {
      tokens.push({ type: 'em', value: raw.slice(1, -1) });
    }

    cursor = index + raw.length;
  }

  if (cursor < text.length) {
    tokens.push({ type: 'text', value: text.slice(cursor) });
  }

  return tokens.filter((token) => token.value.length > 0);
}

export function parseWikiMarkdown(source: string): Block[] {
  return source
    .split(/\n{2,}/)
    .map((block) => block.trim())
    .filter((block) => block.length > 0)
    .map<Block>((block) => {
      const heading = block.match(HEADING_PATTERN);
      if (heading?.[1]) {
        return { type: 'heading', text: heading[1] };
      }

      const lines = block.split('\n');
      if (lines.every((line) => LIST_ITEM_PATTERN.test(line))) {
        return {
          type: 'list',
          items: lines.map((line) => parseInline(line.replace(LIST_ITEM_PATTERN, '').trim())),
        };
      }

      return { type: 'paragraph', tokens: parseInline(block.replace(/\s*\n\s*/g, ' ')) };
    });
}
